            "【死黨口語縮約（Tier 3）】在好朋友之間的普通體對話中，「〜てしまった」極高頻縮約為「〜ちゃった」（如：忘れてしまった ➔ 忘れちゃった、断ってしまった ➔ 断っちゃった）。"
